-- The generated station map: what `setup` discovered, read back by config.lua.
--
-- Two programs care about this file and they used to agree about it only by
-- coincidence -- setup wrote a path, config required a module name, and nothing
-- tied the two together. Both go through here now, so the location is stated once.
--
-- The data itself lives in data/stations.lua: machine-specific, regenerated by
-- `setup`, and deliberately not in the repo. Everything else under mining/ is
-- either code or the config you edit; this is the one file a machine owns.

local stations = {}

-- Module name for require(), and the path setup writes. They have to describe the
-- same file, which is the entire reason this module exists.
stations.MODULE = "data.stations"
stations.DIR = "data"
stations.FILE = "data/stations.lua"

-- What setup last wrote: { database, supply, stations = { [minerAddr] = spec } }.
-- Returns the table, or nil + why -- a machine that has never run setup simply
-- has no file, which is not an error worth shouting about.
function stations.load()
    local ok, data = pcall(require, stations.MODULE)
    if not ok then return nil, "no " .. stations.FILE .. " yet -- run `setup`" end
    if type(data) ~= "table" then return nil, stations.FILE .. " is not a table" end
    return data
end

-- Writes `payload` back, creating data/ if this is the first run. Serialized in
-- COMPACT mode on purpose: the pretty form truncates long tables with "..." and
-- would produce a file that cannot be loaded. Returns the path, or nil + error.
function stations.save(payload, cwd)
    local serialization = require("serialization")
    local filesystem = require("filesystem")
    local shell = require("shell")

    local base = cwd or shell.getWorkingDirectory()
    local dir = filesystem.concat(base, stations.DIR)
    if not filesystem.exists(dir) then filesystem.makeDirectory(dir) end

    local path = filesystem.concat(base, stations.FILE)
    local text = table.concat({
        "-- Generated by mining/setup.lua (automatic). Machine-specific; safe to regenerate.",
        "-- Loaded through lib/stations.lua by config.lua. NOT part of the repo/manifest.",
        "return " .. serialization.serialize(payload),
        "",
    }, "\n")

    local f, ferr = io.open(path, "w")
    if not f then return nil, tostring(ferr), text end
    f:write(text)
    f:close()
    return path
end

return stations
